 #[derive(Debug, Args)]
 pub(crate) struct StackArgs {
     #[command(subcommand)]
     pub(crate) command: StackCommand,
 }

 #[derive(Debug, Subcommand)]
 pub(crate) enum StackCommand {
     /// Show the current stack: tickets, branches, PRs, restack health.
     Show,
