446.     #[test]
447.     fn switch_to_crew_adds_bridge_and_foreman() {
448.         let mut yaml = solo_yaml();
449.         let old = current_mode_str(&yaml);
450.         let changes = compute_changes(&mut yaml, old, InitMode::Crew).unwrap();
451.         assert!(changes.steps_added.contains(&"bridge".to_owned()));
452.         assert!(changes.steps_added.contains(&"foreman".to_owned()));
453.         // Verify pipeline in mutated YAML contains the new steps.
454.         let pipeline = yaml["pipeline"].as_sequence().unwrap();
455.         let ids: Vec<_> = pipeline
456.             .iter()
457.             .filter_map(|s| s.get("id")?.as_str())
458.             .collect();
459.         assert!(ids.contains(&"bridge"));
460.         assert!(ids.contains(&"foreman"));
