112. /// Returns run-ids (directory names) of runs whose manifest has no
113. /// `finished_at`, indicating they are still in progress.
114. fn detect_inflight_runs(repo_root: &Path) -> Vec<String> {
115.     let runs_dir = repo_root.join(".derrick").join("runs");
116.     let mut inflight = Vec::new();
117.     let Ok(entries) = std::fs::read_dir(&runs_dir) else {
118.         return inflight;
119.     };
120.     for entry in entries.flatten() {
121.         let manifest = entry.path().join("manifest.json");
122.         if !manifest.exists() {
123.             continue;
124.         }
125.         let Ok(text) = std::fs::read_to_string(&manifest) else {
126.             continue;
127.         };
128.         let Ok(json) = serde_json::from_str::<serde_json::Value>(&text) else {
129.             continue;
130.         };
131.         // A run is in-flight when finished_at is absent or explicitly null.
132.         let finished = json
133.             .get("finished_at")
134.             .map(|v| !v.is_null())
135.             .unwrap_or(false);
136.         if !finished {
137.             if let Some(name) = entry.file_name().to_str() {
138.                 inflight.push(name.to_owned());
139.             }
140.         }
141.     }
142.     inflight
143. }
